namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)),
        new(3, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-1)),
    ];

    private static readonly string[] SampleMessages =
    [
        "Deployment completed successfully.",
        "You have a new follower.",
        "Scheduled maintenance at midnight.",
        "Your report is ready to download.",
        "Security alert: new login detected.",
        "Weekly summary is available.",
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        // Randomly add 0–1 new notifications each poll
        lock (_lock)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance
            {
                var msg = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications
                    .Where(n => n.Timestamp > since)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private CancellationTokenSource? _cts;
    private DateTime _latestTimestamp;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if state wasn't restored from prerender
        notifications ??= await NotificationService.GetNotificationsAsync();
        _latestTimestamp = notifications.Count > 0
            ? notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = await NotificationService.GetNotificationsSinceAsync(_latestTimestamp);
            if (newer.Count > 0)
            {
                notifications = [..newer, ..notifications!];
                _latestTimestamp = notifications.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

