@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationService
@inject PersistentComponentState ApplicationState
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (_notifications is not null)
    {
        <span class="badge bg-primary ms-2">@_notifications.Count</span>
    }
</h1>

@if (_notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (_notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? _notifications;
    private CancellationTokenSource? _cts;
    private DateTime _latestTimestamp;
    private PersistingComponentStateSubscription _persistSub;

    protected override async Task OnInitializedAsync()
    {
        _persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

        if (!ApplicationState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            _notifications = await NotificationService.GetNotificationsAsync();
        }
        else
        {
            _notifications = restored;
        }

        _latestTimestamp = _notifications is { Count: > 0 }
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender — safe to start polling
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = await NotificationService.GetNotificationsSinceAsync(_latestTimestamp);
            if (newer.Count > 0)
            {
                _notifications = [..newer, .._notifications!];
                _latestTimestamp = _notifications.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

